(5555315, 802922, 83629, '<td valign="top">I love the way the water leads your eye to the mountain.  Contrast and texture are nice.</td>', 'I love the way the water leads your eye to the mountain.  Contrast and texture are nice.', '2009-07-02 09:41:16.000000', NULL, 1),
(5555316, 802316, 83629, '<td valign="top">Great textural and color contrast!</td>', 'Great textural and color contrast!', '2009-07-02 09:42:03.000000', NULL, 1),
(5555327, 803252, 107423, '<td valign="top">Beautiful Capture! A personal favorite of this challenge!</td>', 'Beautiful Capture! A personal favorite of this challenge!', '2009-07-02 10:06:48.000000', NULL, 1),
(5555329, 802236, 107423, '<td valign="top">Beautiful colors!</td>', 'Beautiful colors!', '2009-07-02 10:09:57.000000', NULL, 1),
(5555857, 803471, 92403, '<td valign="top">I really hope this one does well, it''s my favorite of the challenge.<br/>Very interesting profile, great textures and use of contrast. Congrats!</td>', 'I really hope this one does well, it''s my favorite of the challenge.Very interesting profile, great textures and use of contrast. Congrats!', '2009-07-02 15:38:07.000000', NULL, 1),
(5555858, 802822, 92403, '<td valign="top">Interesting how something so scary can be good looking... <br/>"I''m not happy, but I will after I eat you!"<br/>Very cool!</td>', 'Interesting how something so scary can be good looking... "I''m not happy, but I will after I eat you!"Very cool!', '2009-07-02 15:39:43.000000', NULL, 1),
(5555859, 803527, 92403, '<td valign="top">Oh... soap bubbles! I used to play with them too. <br/>I''m very jealous you were able to capture one in such a flawless way. Great job!</td>', 'Oh... soap bubbles! I used to play with them too. I''m very jealous you were able to capture one in such a flawless way. Great job!', '2009-07-02 15:40:54.000000', NULL, 1),
(5555862, 802211, 92403, '<td valign="top">This looks impressive!</td>', 'This looks impressive!', '2009-07-02 15:41:17.000000', NULL, 1),
(5555865, 802490, 92403, '<td valign="top">A definite contrast both in technique and subject. Well done!</td>', 'A definite contrast both in technique and subject. Well done!', '2009-07-02 15:41:54.000000', NULL, 1),
(5555866, 803259, 92403, '<td valign="top">Really interesting perspective on something so many people have photographed already, plus it looks flawless! Excellent job.</td>', 'Really interesting perspective on something so many people have photographed already, plus it looks flawless! Excellent job.', '2009-07-02 15:43:03.000000', NULL, 1),
(5555869, 803563, 92403, '<td valign="top">Absolutely love the gradient. I bet you''ll do very well in this challenge!</td>', 'Absolutely love the gradient. I bet you''ll do very well in this challenge!', '2009-07-02 15:43:45.000000', NULL, 1),
(5555871, 802978, 92403, '<td valign="top">Like this for its spontaneity. Definitely different from the bunch, in a good way!</td>', 'Like this for its spontaneity. Definitely different from the bunch, in a good way!', '2009-07-02 15:44:33.000000', NULL, 1),
(5555960, 803220, 106349, '<td valign="top">He looks like he''s sweating. :o)</td>', 'He looks like he''s sweating. :o)', '2009-07-02 16:32:52.000000', NULL, 1),
(5555962, 802968, 106349, '<td valign="top">I would like this better if I could see the trunk a little. It just seems cut off. Cool tree, though.</td>', 'I would like this better if I could see the trunk a little. It just seems cut off. Cool tree, though.', '2009-07-02 16:34:23.000000', NULL, 1),
(5555965, 802005, 106349, '<td valign="top">Good shot of an everyday thing that many of us see on a regular basis. - 6</td>', 'Good shot of an everyday thing that many of us see on a regular basis. - 6', '2009-07-02 16:36:00.000000', NULL, 1),
(5555971, 802700, 106349, '<td valign="top">This is just too blurry for my taste. It also seems a little strange that his feet are cut off.</td>', 'This is just too blurry for my taste. It also seems a little strange that his feet are cut off.', '2009-07-02 16:37:36.000000', NULL, 1),
(5555974, 803153, 106349, '<td valign="top">This is a great example of contast. The flower itself was done very well and the ant just added to it. - 7</td>', 'This is a great example of contast. The flower itself was done very well and the ant just added to it. - 7', '2009-07-02 16:38:25.000000', NULL, 1),
(5555977, 802998, 106349, '<td valign="top">Good use of contrast but, in my opinion, it needs some sort of subject to be a really "wow" picture. - 5</td>', 'Good use of contrast but, in my opinion, it needs some sort of subject to be a really "wow" picture. - 5', '2009-07-02 16:39:33.000000', NULL, 1),
(5555979, 803061, 106349, '<td valign="top">Nice tribute! (and nice contrast, too). - 7</td>', 'Nice tribute! (and nice contrast, too). - 7', '2009-07-02 16:39:58.000000', NULL, 1),
(5555981, 803482, 106349, '<td valign="top">ADORABLE picture, but I wouldn''t see this as a picture that particular demonstrates "high contrast". - 4</td>', 'ADORABLE picture, but I wouldn''t see this as a picture that particular demonstrates "high contrast". - 4', '2009-07-02 16:40:56.000000', NULL, 1),
(5555983, 802883, 106349, '<td valign="top">I like the contrast in this picture. It''s a moving photograph. - 6</td>', 'I like the contrast in this picture. It''s a moving photograph. - 6', '2009-07-02 16:41:30.000000', NULL, 1),
(5556192, 802466, 106349, '<td valign="top">I like the composition on this shot. Makes a nice B&amp;W.</td>', 'I like the composition on this shot. Makes a nice B&W.', '2009-07-02 18:37:20.000000', NULL, 1),
(5556193, 803195, 106349, '<td valign="top">I suppose it does have contrast, but other than that, it''s missing interest.</td>', 'I suppose it does have contrast, but other than that, it''s missing interest.', '2009-07-02 18:38:01.000000', NULL, 1),
(5556224, 802909, 106349, '<td valign="top">A little blurry for my taste.</td>', 'A little blurry for my taste.', '2009-07-02 18:48:09.000000', NULL, 1),
(5556264, 803634, 106349, '<td valign="top">I think this is a very good example of "high contrast" Beautiful blue sky...</td>', 'I think this is a very good example of "high contrast" Beautiful blue sky...', '2009-07-02 18:57:42.000000', NULL, 1),
(5556267, 803401, 106349, '<td valign="top">Nice focus on an animal that has a hard time sitting still. The contrast is great, too. - 7</td>', 'Nice focus on an animal that has a hard time sitting still. The contrast is great, too. - 7', '2009-07-02 18:58:32.000000', NULL, 1),
(5556278, 803189, 106349, '<td valign="top">The contrast is great but I''d like the flower a little more in focus.</td>', 'The contrast is great but I''d like the flower a little more in focus.', '2009-07-02 18:59:38.000000', NULL, 1),
(5556642, 803195, 106056, '<td valign="top">k</td>', 'k', '2009-07-02 21:18:31.000000', NULL, 1),
(5556974, 803521, 6667, '<td valign="top">Nicely done. BOL  I am guessing someone spent a day downtown!</td>', 'Nicely done. BOL  I am guessing someone spent a day downtown!', '2009-07-02 23:35:22.000000', NULL, 1),
