(5557152, 802206, 51747, '<td valign="top">Now this is high contrast! Nice job of it too.</td>', 'Now this is high contrast! Nice job of it too.', '2009-07-03 00:29:12.000000', NULL, 1),
(5557542, 802972, 105470, '<td valign="top">The best use of man made colors against a nature backdrop that I''ve seen in this challenge which to me is what its about.</td>', 'The best use of man made colors against a nature backdrop that I''ve seen in this challenge which to me is what its about.', '2009-07-03 06:39:53.000000', NULL, 1),
(5557549, 802963, 105470, '<td valign="top">Great capture of the Suns Rays against the shadow of the trees.</td>', 'Great capture of the Suns Rays against the shadow of the trees.', '2009-07-03 06:42:16.000000', NULL, 1),
(5557567, 802634, 105470, '<td valign="top">Love the capture.  Could have been called "Get your head outta the clouds"<br/>lol.. Good color contrast and eye catching.</td>', 'Love the capture.  Could have been called "Get your head outta the clouds"lol.. Good color contrast and eye catching.', '2009-07-03 06:44:49.000000', NULL, 1),
(5557571, 803127, 105470, '<td valign="top">Good location choice for this.</td>', 'Good location choice for this.', '2009-07-03 06:46:16.000000', NULL, 1),
(5557574, 803472, 105470, '<td valign="top">Very good use of suroundings and great composition. Love it.</td>', 'Very good use of suroundings and great composition. Love it.', '2009-07-03 06:48:24.000000', NULL, 1),
(5557580, 802005, 105470, '<td valign="top">Would be a great addition for the cell phone commercial "Bars".  I like the whole thing.</td>', 'Would be a great addition for the cell phone commercial "Bars".  I like the whole thing.', '2009-07-03 06:50:33.000000', NULL, 1),
(5557582, 803128, 105470, '<td valign="top">Very nice, love the composition.</td>', 'Very nice, love the composition.', '2009-07-03 06:51:27.000000', NULL, 1),
(5557628, 803252, 88791, '<td valign="top">Beautiful ... and contrasty too!</td>', 'Beautiful ... and contrasty too!', '2009-07-03 07:35:26.000000', NULL, 1),
(5557629, 803518, 88791, '<td valign="top">Very well done.</td>', 'Very well done.', '2009-07-03 07:36:46.000000', NULL, 1),
(5557993, 803602, 106484, '<td valign="top">Great colour. My only problem with it is the cropped tentacle.</td>', 'Great colour. My only problem with it is the cropped tentacle.', '2009-07-03 15:11:52.000000', NULL, 1),
(5558072, 801999, 106484, '<td valign="top">I saw something like this in Singapore, amazing colours....such a shame to lose them. Nice shot though, if a little overexposed.</td>', 'I saw something like this in Singapore, amazing colours....such a shame to lose them. Nice shot though, if a little overexposed.', '2009-07-03 16:50:16.000000', NULL, 1),
(5558073, 802785, 106484, '<td valign="top">Nice image but there''s a need for just a little more depth of field.</td>', 'Nice image but there''s a need for just a little more depth of field.', '2009-07-03 16:51:27.000000', NULL, 1),
(5558075, 803165, 106484, '<td valign="top">It''s a bit noisy in the shadows and it''s a tad over-sharpened (you can see the jagged edge on the tee). It''s a nice composition though.</td>', 'It''s a bit noisy in the shadows and it''s a tad over-sharpened (you can see the jagged edge on the tee). It''s a nice composition though.', '2009-07-03 16:53:10.000000', NULL, 1);
