(5558866, 803553, 106349, '<td valign="top">What an adorable picture. Her eyes really make the whole picture pop.</td>', 'What an adorable picture. Her eyes really make the whole picture pop.', '2009-07-04 09:55:54.000000', NULL, 1),
(5558868, 802535, 106349, '<td valign="top">You did a great job in making an ugly subject beautiful.</td>', 'You did a great job in making an ugly subject beautiful.', '2009-07-04 09:56:47.000000', NULL, 1),
(5558870, 803483, 106349, '<td valign="top">I like the concept of the picture but it just seems a little to blurry/grainy. I do agree that it makes a nice "high contrast" entry.</td>', 'I like the concept of the picture but it just seems a little to blurry/grainy. I do agree that it makes a nice "high contrast" entry.', '2009-07-04 09:57:41.000000', NULL, 1),
(5558872, 803026, 106349, '<td valign="top">Very nice colors &amp; contrast!</td>', 'Very nice colors & contrast!', '2009-07-04 10:00:09.000000', NULL, 1),
(5558876, 803269, 106349, '<td valign="top">This is truly beautiful. Can''t wait to find out where it is (so I can put it on my "places I need to visit" list).</td>', 'This is truly beautiful. Can''t wait to find out where it is (so I can put it on my "places I need to visit" list).', '2009-07-04 10:02:34.000000', NULL, 1),
(5558879, 803472, 106349, '<td valign="top">Beautiful colors in the brick! You really found a perfect way to add a subject (you) while letting the colors in the brick take over most of the picture.</td>', 'Beautiful colors in the brick! You really found a perfect way to add a subject (you) while letting the colors in the brick take over most of the picture.', '2009-07-04 10:05:24.000000', NULL, 1),
(5558948, 803165, 70036, '<td valign="top">Would have been better if tee was straight.  Golf ball is blow out in upper left.   Certainly high contrast.</td>', 'Would have been better if tee was straight.  Golf ball is blow out in upper left.   Certainly high contrast.', '2009-07-04 11:35:59.000000', NULL, 1),
(5558949, 803403, 70036, '<td valign="top">Oversaturated ?</td>', 'Oversaturated ?', '2009-07-04 11:36:16.000000', NULL, 1),
(5558951, 802922, 70036, '<td valign="top">Oversaturated.   Too much loss of detail.</td>', 'Oversaturated.   Too much loss of detail.', '2009-07-04 11:37:34.000000', NULL, 1),
(5558953, 802934, 70036, '<td valign="top">Good use of effect.</td>', 'Good use of effect.', '2009-07-04 11:38:35.000000', NULL, 1),
(5558956, 803115, 70036, '<td valign="top">Great perspective.</td>', 'Great perspective.', '2009-07-04 11:39:03.000000', NULL, 1),
(5558957, 803563, 70036, '<td valign="top">Great image.</td>', 'Great image.', '2009-07-04 11:39:14.000000', NULL, 1),
(5558958, 802236, 70036, '<td valign="top">Horizon is not straight.  (I do that all the time.)</td>', 'Horizon is not straight.  (I do that all the time.)', '2009-07-04 11:40:15.000000', NULL, 1),
(5558964, 802956, 70036, '<td valign="top">Great picture, however everything seems to be in the mid-tones.  Not really high contrast.  But a good picture.</td>', 'Great picture, however everything seems to be in the mid-tones.  Not really high contrast.  But a good picture.', '2009-07-04 11:42:12.000000', NULL, 1),
(5558966, 803259, 70036, '<td valign="top">Excellent.   Good composition and good take on the challenge theme.</td>', 'Excellent.   Good composition and good take on the challenge theme.', '2009-07-04 11:43:16.000000', NULL, 1),
(5558968, 803520, 70036, '<td valign="top">Good take on the theme.  Good composition.</td>', 'Good take on the theme.  Good composition.', '2009-07-04 11:44:03.000000', NULL, 1),
(5558970, 803447, 70036, '<td valign="top">Excellent clouds, but foreground seems indistinct with loss of shadow detail in that long shadow.</td>', 'Excellent clouds, but foreground seems indistinct with loss of shadow detail in that long shadow.', '2009-07-04 11:45:40.000000', NULL, 1),
(5558971, 803038, 70036, '<td valign="top">Good composition, good use of contrast..</td>', 'Good composition, good use of contrast..', '2009-07-04 11:46:55.000000', NULL, 1),
(5558972, 803526, 70036, '<td valign="top">Interesting shot, but not much high contrast.  Everything is in the mid-tones.</td>', 'Interesting shot, but not much high contrast.  Everything is in the mid-tones.', '2009-07-04 11:47:34.000000', NULL, 1),
(5558973, 803527, 70036, '<td valign="top">Excellent use of high contrast.  I think you understood the challenge.  Good composition and it tells a story.    One of the best uses of contrast in this challenge.</td>', 'Excellent use of high contrast.  I think you understood the challenge.  Good composition and it tells a story.    One of the best uses of contrast in this challenge.', '2009-07-04 11:49:17.000000', NULL, 1),
(5558975, 802860, 70036, '<td valign="top">This image seems to be all mid-tone, even though the background is dark.   Not much contrast.</td>', 'This image seems to be all mid-tone, even though the background is dark.   Not much contrast.', '2009-07-04 11:50:29.000000', NULL, 1),
(5558976, 803127, 70036, '<td valign="top">Good high contrast image.</td>', 'Good high contrast image.', '2009-07-04 11:51:21.000000', NULL, 1),
(5558977, 803324, 70036, '<td valign="top">Good shot, but very little contrast.   Mostly mid-tone.</td>', 'Good shot, but very little contrast.   Mostly mid-tone.', '2009-07-04 11:54:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5558979, 802778, 70036, '<td valign="top">Great composition.  Good use of contrast.</td>', 'Great composition.  Good use of contrast.', '2009-07-04 11:55:07.000000', NULL, 1),
(5558980, 802477, 70036, '<td valign="top">Lots of contrast, but the busy background detracts from the (centered) subject.  A shallower DOF may have helped this.</td>', 'Lots of contrast, but the busy background detracts from the (centered) subject.  A shallower DOF may have helped this.', '2009-07-04 11:56:14.000000', NULL, 1),
(5558981, 802700, 70036, '<td valign="top">Lack of shadow detail detracts.</td>', 'Lack of shadow detail detracts.', '2009-07-04 11:56:33.000000', NULL, 1),
(5558985, 802658, 70036, '<td valign="top">Excellent.    I do not think it needs so much border.  The image could stand on its own.    Good use of contrast.</td>', 'Excellent.    I do not think it needs so much border.  The image could stand on its own.    Good use of contrast.', '2009-07-04 11:57:51.000000', NULL, 1),
(5558986, 803195, 70036, '<td valign="top">No contrast. No real subject.</td>', 'No contrast. No real subject.', '2009-07-04 11:58:26.000000', NULL, 1),
(5558987, 803151, 70036, '<td valign="top">Beautiful.  Good DOF.   One of best in challenge.</td>', 'Beautiful.  Good DOF.   One of best in challenge.', '2009-07-04 11:59:16.000000', NULL, 1),
(5558991, 803540, 70036, '<td valign="top">Good use of contrast.   Composition could use help.  Too much open space, perhaps, at the top.  It puts her eyes in the center where they would have been more effective on the thirds.</td>', 'Good use of contrast.   Composition could use help.  Too much open space, perhaps, at the top.  It puts her eyes in the center where they would have been more effective on the thirds.', '2009-07-04 12:00:59.000000', NULL, 1),
(5558992, 803528, 70036, '<td valign="top">Very good.  Good composition.</td>', 'Very good.  Good composition.', '2009-07-04 12:01:57.000000', NULL, 1),
(5558994, 803287, 70036, '<td valign="top">Nice work with the shadows and highlights.   Clouds are great to work with.</td>', 'Nice work with the shadows and highlights.   Clouds are great to work with.', '2009-07-04 12:02:52.000000', NULL, 1),
(5558995, 803290, 70036, '<td valign="top">Good use of contrast and color.</td>', 'Good use of contrast and color.', '2009-07-04 12:03:18.000000', NULL, 1),
(5558996, 803026, 70036, '<td valign="top">Excellent composition and use of contrast.</td>', 'Excellent composition and use of contrast.', '2009-07-04 12:04:25.000000', NULL, 1),
(5558997, 802206, 70036, '<td valign="top">Great.  Bothered a bit that her shoulder is cut off when there is open space on the right.</td>', 'Great.  Bothered a bit that her shoulder is cut off when there is open space on the right.', '2009-07-04 12:05:13.000000', NULL, 1),
